from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_FLOOR, ROUND_CEILING, ROUND_DOWN, getcontext, localcontext

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# Every option that takes a value: its allowed values, and what it is when the command line does not say.
OPTIONS = {"format": FORMATS, "kind": ("inner", "left"), "keep": ("first", "last")}
DEFAULTS = {"format": "text", "kind": "inner", "keep": "first"}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def fmt_2dp(number):
    """A Decimal rounded half up to two decimals and always printed with two."""
    return fmt_decimal(number.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)



# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_at_least(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _cell_number(table, row_number, column, value):
    """The Decimal in a cell; TabulaError naming the file, the data row (1-based, file order) and the column."""
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%s: row %d: column %r: %r is not a number" % (table.source, row_number, column, value))
    return number


def cmd_show(args, opts):

def _parse_aggregate(text):
    """(name, column or None) from `count` or `NAME:COLUMN`; UsageError when it is neither."""
    name, colon, column = text.partition(":")
    if text == "count" or (colon and column and name in GROUP_NUMERIC):
        return name, (column if colon else None)
    raise UsageError("group: bad aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % text)


def cmd_group(args, opts):
    _need_at_least(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        dup = next(a for i, a in enumerate(args[2:]) if a in args[2:i + 2])
        raise UsageError("group: aggregate %r given twice" % dup)
    aggregates = [_parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    wanted = [(name, None if column is None else (table.index(column), column)) for name, column in aggregates]
    names = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("result would have column %r twice" % name)
    groups = {}
    for n, row in enumerate(table.rows, 1):
        members = groups.setdefault(row[by], [])
        members.append([None if w is None else _cell_number(table, n, w[1], row[w[0]]) for _, w in wanted])
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for key, members in groups.items():
            out = [key]
            for i, (name, _) in enumerate(wanted):
                values = [m[i] for m in members]
                if name == "count":
                    out.append(str(len(members)))
                elif name == "sum":
                    out.append(fmt_decimal(sum(values, Decimal(0))))
                elif name == "min":
                    out.append(fmt_decimal(min(values)))
                elif name == "max":
                    out.append(fmt_decimal(max(values)))
                else:
                    out.append(fmt_2dp(sum(values, Decimal(0)) / len(values)))
            rows.append(out)
    return Table(names, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left = load(args[0])
    left_at = left.index(args[2])
    right = load(args[1])
    right_at = right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != right_at]
    names = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                            for i in kept]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("join: result would have column %r twice" % name)
    matches = {}
    for row in right.rows:
        matches.setdefault(row[right_at], []).append([row[i] for i in kept])
    empty = [""] * len(kept)
    rows = []
    for row in left.rows:
        found = matches.get(row[left_at])
        if found:
            rows.extend(row + extra for extra in found)
        elif opts["kind"] == "left":
            rows.append(row + empty)
    return Table(names, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row = table.index(args[1])
    at_col = table.index(args[2])
    at_val = table.index(args[3])
    sums = {}
    heads = {}
    for n, row in enumerate(table.rows, 1):
        head = row[at_col]
        if head == "":
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, n, args[2]))
        if head == args[1]:
            raise TabulaError("%s: row %d: column %r: value %r is the name of the row column"
                              % (table.source, n, args[2], head))
        number = _cell_number(table, n, args[3], row[at_val])
        heads.setdefault(head, None)
        sums.setdefault(row[at_row], {}).setdefault(head, []).append(number)
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for key, cells in sums.items():
            rows.append([key] + [fmt_decimal(sum(cells[h], Decimal(0))) if h in cells else "0" for h in heads])
    return Table([args[1]] + list(heads), rows, table.source)


def cmd_dedupe(args, opts):
    _need_at_least(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    at = [table.index(name) for name in args[1:]]
    chosen = {}
    for n, row in enumerate(table.rows):
        key = tuple(row[i] for i in at)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = n
    keep = set(chosen.values())
    return table.with_rows([row for n, row in enumerate(table.rows) if n in keep])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by one or more columns"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every condition holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per value of a column, with aggregates"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "two files joined on a column"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "distinct values of a column turned into columns of sums"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "rows repeated on the key columns dropped"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG,
             "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = dict(DEFAULTS), [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # the output could not be written (a full disk, say); the rest of it must not be flushed again at exit
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
